'use strict';
// Shared by the catalog, local player and exported design-system artifacts.
const playerSystem = {
  revision: '2026-11-16.profile-19',
  tokens: {workspaceInset:"24px",artistStructuralBackground:"transparent",artistPlayerPadding:"32px",rowPlayOpacity:0.9,genreAspectRatio:'1 / 1',sessionAspectRatio:'16 / 9',catalogGap:'24px',sidebarBackground:'transparent',contextBackground:'transparent',dividerWidth:'1px',dividerColor:'color-mix(in srgb, var(--noodo-accent, var(--accent)) 22%, var(--noodo-background, var(--background)))',rowPaddingBlock:'6px',rowMinHeight:'60px',albumAspectRatio:'1 / 1',galleryColumns:4,libraryRailWidth:'48px',albumMaxWidth:'280px',dockGlow:'0 -10px 42px color-mix(in srgb, var(--primary) 18%, transparent), 0 0 24px color-mix(in srgb, var(--accent) 10%, transparent)'},
  rules: [
    ['Superficies del perfil','Cabecera, mini reproductor, detalle de contacto y tarjetas de booking transparentes: sin degradado, glow ni fondo de card. Mantener divisores estructurales. Tipo de perfil en tamaño heading, arriba a la derecha del nombre.'],
    ['Alineación de columnas','Inset superior compartido de 24 px. Biblioteca fija debajo del header, con scroll propio si su contenido excede el alto y divisor hasta el borde inferior. La columna central se desplaza de forma independiente visualmente.'],
    ['Mini reproductor independiente','Cinco canciones, pista, progreso y volumen propios. Al reproducir aquí se pausa el global sin modificar su canción, posición, cola, mezcla ni repetición. Si el mini está sonando al abandonar el perfil, se pausa y reanuda el global. Reproducir el global pausa el mini. Nunca deben sonar ambos.'],
    ['Galería integrada','Abrir fotografías dentro del mismo contenedor de Galería. Controles anterior, siguiente y regreso a cuadrícula; flechas y Escape con foco dentro del visor. Conservar altura, posición de página y foco de la miniatura.'],
    ['Bandas recomendadas','Carrusel de ocho perfiles con portada 1:1 y nombre enlazado. Deslizamiento horizontal, controles anterior/siguiente y teclado. Antes de las canciones en Inicio; no duplicar en Guardados ni búsquedas.'],
    ['Regreso uniforme','Control Volver en la esquina superior izquierda del centro, antes del título. Regresa a la vista de origen conservando posición, foco y reproducción. Detalles anidados regresan un nivel cada vez.'],
    ['Sesiones y plataformas','Detalle de video transparente, sin degradado. Accesos a YouTube y Spotify: URL oficial cuando exista; en su ausencia, identificar la acción como Buscar en la plataforma. Nunca inventar un enlace a una publicación.'],
    ['Concierto compacto','Variante del listado de conciertos para la columna derecha: bloque de fecha, categoría, nombre, lugar y hora, sin fotografía. Acción de entradas únicamente con icono de ticket en botón 1:1 de 44 px, etiqueta accesible y tooltip Reservar entrada o Comprar tickets. Adaptar la distribución al ancho sin reducir la tipografía.'],
    ['Catálogo de géneros','GenreCard siempre 1:1, tanto en Inicio como en Explorar géneros. Grid adaptable: 6 columnas amplias, 4 medianas, 3 compactas y 2 móviles. Cada tarjeta abre todos los perfiles del género; el chip de género del artista abre el mismo resultado. Usar géneros del catálogo, con estado vacío si no hay artistas.'],
    ['Sessions de video','Extender SessionVideo a SessionVideoCard: poster 16:9, play centrado, duración, título, artista y guardar. Grid de 2 columnas en escritorio y 1 en móvil; abre video en el centro manteniendo dock. Las sesiones no se mezclan en la cola de audio.'],
    ['Contexto fijo','Panel derecho transparente, siempre visible en la vista de escucha y en el detalle de álbum en escritorio, sin controles de plegado. Canción, Artista, Conciertos y Letras cambian el resumen en esa misma columna, sin navegación. Solo el nombre enlazado abre el perfil. En móvil, apertura superpuesta desde header.'],
    ['Navegación y perfiles','Inicio, Canciones, Sessions y Guardados sin contadores. El perfil distingue Banda, Artista, DJ o Productor. Las pills de integrantes enlazan perfiles personales; Contactar abre booking y prensa.'],
    ['Banner multipropósito','Un espacio promocional solo en Inicio: canciones sin búsqueda ni filtro de género. Ocultarlo en Guardados, Sessions, búsquedas, géneros, perfiles y detalles. Mostrarlo de nuevo al regresar al inicio solo si no fue cerrado. Ubicarlo en la columna central antes de las canciones. Configurable por campaña: tipo, imagen, etiqueta, título, texto, CTA y destino para artista, canción, sesión, evento o publicidad. Publicidad debe identificarse como tal. Cierre accesible de 44 × 44 px; recordar el cierre durante la sesión por campaña. Nunca iniciar reproducción automáticamente.'],
    ['Iconos y orden de canción','Iconos en caja cuadrada 1:1 sin deformación. Play/pausa al inicio de cada fila, antes de portada y título; eliminar numeración. Play de 44 × 44 px con SVG de 22 × 22 px; opacidad base 0.9 y opacidad completa al pasar el cursor o recibir foco. Guardar y Apoyar permanecen como acciones separadas.'],
    ['Estructura global','Usar todo el ancho disponible, con márgenes de 20 px en escritorio y 10 px en móvil. Header y reproductor persistentes. Biblioteca plegable a un rail; su toggle vive junto a Tu biblioteca. En el perfil del artista ocultar el contexto derecho y mostrarlo de nuevo al abrir un álbum o regresar a escucha.'],
    ['Contenido central','Perfiles, letras, conciertos, cola, álbumes, galería y videos se abren en el centro. Los detalles permiten regresar conservando la posición. Al seleccionar una canción, mostrar primero una síntesis en el panel derecho. Merchandising no forma parte de esta versión.'],
    ['Navegación persistente del artista','Header global siempre visible. Menú del artista fijo debajo; al salir la cabecera, mostrar foto y nombre antes de las secciones. Adaptar el contenido al ancho real del centro y mantener la escucha al navegar.'],
    ['Conciertos en lista','Filas con fecha, miniatura, categoría, nombre enlazado al detalle, lugar, hora y acción de tickets. Comprar tickets en eventos de pago; Reservar entrada en gratuitos. Acción de tickets y flecha de detalle siempre juntas, alineadas a la derecha; en espacios estrechos ambas pasan juntas a la segunda fila. Detalle central; mostrar disponibilidad antes de reservar o pagar. Glow suave sin borde decorativo.'],
    ['Mini reproductor del artista','Cinco canciones por artista. Estado independiente del global y controles de anterior, reproducir/pausar, siguiente, avance y volumen. Superficie transparente, padding de 32 px, divisor izquierdo y alto completo en la tercera columna de la cabecera. En móvil apilar y mover el divisor arriba. Cada fila incluye Añadir a playlist como acción independiente. Crear o elegir una playlist, guardar en este navegador y evitar canciones duplicadas.'],
    ['Detalle de álbum','Portada 1:1 idéntica a la del catálogo, título, tipo, año, nombre enlazado de la banda, biografía y duración. Reutilizar CompactTrackRow y sus acciones Play, Guardar y Apoyar. Selección, progreso y reproducción sincronizados con el dock persistente. Información de la banda a la derecha; regreso al perfil conserva la escucha.'],
    ['Álbumes cuadrados','Portadas 1:1, con título y metadatos fuera. Cuatro columnas iguales en escritorio, máximo 280 px por portada; conservar el tamaño aunque haya menos de cuatro. Dos columnas en centros de 680 px o menos.'],
    ['Galería fotográfica','Doce imágenes en cuatro columnas y tres filas en escritorio. Reducir a dos columnas en centros menores de 440 px. Abrir la imagen y su navegación dentro del contenedor de la galería; conservar la procedencia de los recursos en la documentación interna.'],
    ['Redes del artista','YouTube, Spotify, SoundCloud, Deezer, web y TikTok mediante iconos de 22 px en controles de 44 px, con nombre accesible y tooltip. Mostrar estado pendiente cuando no exista URL oficial; nunca enlazar a cuentas inventadas.'],
    ['Reproductor persistente','La barra vive fuera de las vistas de canciones y artista. Navegar no recrea el reproductor: mantiene pista, progreso, pausa, volumen, mezcla y repetición. Los enlaces Atrás/Adelante también conservan la escucha. Reservar espacio inferior para la barra. Fondo oscuro y halo suave mediante player-dock-glow para separar la barra del contenido, sin borde decorativo.'],
    ['Apoyo al artista','Cada canción incluye Apoyar, separado de Guardar. Abre en la columna central una muestra de aportes en COP con importes seleccionables y confirmación explícita sin cobro. En móvil usa icono con nombre accesible.'],
    ['Encabezados de columnas','Tu biblioteca en accent. La columna de información empieza con la fila de iconos, sin el título En detalle.'],
    ['Página de artista','Cabecera con retrato, género único, nombre, ubicación, biografía y equipo. Mini reproductor en la cabecera. Después: álbumes; una fila con conciertos a la izquierda y galería a la derecha; y Multimedia. Contactar en la cabecera abre booking y prensa. Sin columna derecha ni merchandising. Redes y contactos oficiales pendientes deben comunicarse como tales.'],
    ['Pestañas de contexto','Cuatro iconos en una fila horizontal: canción, artista, conciertos y letras. Activo únicamente en accent, sin borde ni indicador inferior; conservar el anillo de foco solo para navegación con teclado; etiquetas accesibles, tooltip nativo, foco visible y navegación con flechas. Objetivo mínimo de 44 px de alto.'],
    ['Acceso al perfil','La portada del reproductor enlaza al perfil del artista con icono de vínculo. No abrir un modal de biografía ni duplicar el perfil dentro del reproductor. Mantener la barra y el estado al navegar.'],
    ['Cabecera de artista','Tres columnas en escritorio: retrato a la izquierda, información en el centro y reproductor independiente a la derecha. Los tres comienzan a la misma altura. En anchos intermedios, el reproductor pasa a una fila completa; en móvil, se apilan foto, información y reproductor. Texto alineado con el borde superior del retrato. Debajo de la biografía, integrantes como píldoras de foto y nombre, enlazadas a su perfil. Acciones y redes ancladas a la base de la foto. Contactar usa icono y texto; abre booking y prensa en el centro, sin duplicar una sección al pie. En móvil apilar sin espacios artificiales.'],
    ['Biblioteca estructural','Fondo transparente y divisor derecho de 1 px desde el header hasta el borde inferior de la pantalla. Toggle junto al título accent; al plegar, conservar un rail con el control para reabrir. Solo navegación, sin bloque Tu escucha ni progreso duplicado. En móvil, panel abierto superpuesto y opaco.'],
    ['Fila compacta','Padding vertical de 6 px, altura mínima de 60 px y controles de 44 px de alto. La fila puede crecer si el texto lo necesita. Conservar título y artista; no reducir la tipografía para compactar.'],
    ['Selección y reproducción','Primer clic en cualquier zona no interactiva de una fila o en su título: seleccionar y mostrar información a la derecha sin interrumpir la pista que suena. Si ya está seleccionada, otro clic reproduce o reanuda. Enter y Espacio equivalentes. Play, Guardar y Apoyar actúan independientemente. Borde accent y relleno de progreso solo para reproducción; selección y reproducción son estados distintos.'],
    ['Contexto del artista','Superficie transparente, sin degradado, glow, borde ni radio de card; hereda el fondo de la página. En móvil, el panel superpuesto usa background para mantener legibilidad. El enlace muestra el nombre de la banda o artista del perfil asociado a la canción seleccionada, nunca el título de la canción ni el nombre de un integrante. La tercera columna muestra la canción seleccionada y accesos a su información. Puede ser distinta de la pista del dock. En páginas de artista se oculta para ampliar el centro; al volver a escucha o abrir un álbum se muestra siempre.'],
    ['Contenido editorial','Interfaz sin notas de prototipo, referencias a IA ni encabezados decorativos. Títulos de sección en accent y nombres concretos. Conservar procedencia de recursos en documentación interna. Datos o servicios ausentes usan estados claros: no disponible, sin resultados o error; no simular cobros ni videos inexistentes.']
  ]
};
function playerTokenCSS(){return `:root{\n  --workspace-inset: ${playerSystem.tokens.workspaceInset};\n  --artist-structural-background: ${playerSystem.tokens.artistStructuralBackground};\n  --artist-player-padding: ${playerSystem.tokens.artistPlayerPadding};\n  --player-row-play-opacity: ${playerSystem.tokens.rowPlayOpacity};\n  --genre-card-ratio: ${playerSystem.tokens.genreAspectRatio};\n  --session-card-ratio: ${playerSystem.tokens.sessionAspectRatio};\n  --catalog-gap: ${playerSystem.tokens.catalogGap};\n  --player-sidebar-background: ${playerSystem.tokens.sidebarBackground};\n  --player-context-background: ${playerSystem.tokens.contextBackground};\n  --player-divider-width: ${playerSystem.tokens.dividerWidth};\n  --player-divider-color: ${playerSystem.tokens.dividerColor};\n  --player-row-padding-block: ${playerSystem.tokens.rowPaddingBlock};\n  --player-row-min-height: ${playerSystem.tokens.rowMinHeight};\n  --artist-album-ratio: ${playerSystem.tokens.albumAspectRatio};\n  --artist-gallery-columns: ${playerSystem.tokens.galleryColumns};\n  --shell-rail-width: ${playerSystem.tokens.libraryRailWidth};\n  --artist-album-max-width: ${playerSystem.tokens.albumMaxWidth};\n  --player-dock-glow: ${playerSystem.tokens.dockGlow};\n}\n`;}
const playerTokenStyle=document.createElement('style');playerTokenStyle.textContent=playerTokenCSS();document.head.appendChild(playerTokenStyle);
